from pathlib import Path

p=Path('prompt-engine.js')
s=p.read_text()

def rep(old,new):
    global s
    n=s.count(old)
    if n!=1: raise SystemExit(f'Expected exactly one procedure text; found {n}: {old[:120]!r}')
    s=s.replace(old,new,1)

