# Semantic acceptance: prevent these specific regressions from returning.
p=Path('verify-prompt-semantics.mjs'); t=p.read_text(); marker='// Specialist stage-procedure regression checks.'
if marker not in t:
    t += r'''

// Specialist stage-procedure regression checks.
{
 const p=baseProject();
 const checks=[
  [8,['actual domain, artifact types, toolchain, and scale','multi-file or tool-generated work']],
  [9,['domain/toolchain completeness']],
  [10,['component completeness','executed unchanged']],
  [11,['RUN_ID and CONTEXT_ID','exact execution lane']],
  [12,['current operation scope']],
  [17,['exact supplied iteration, candidate, run, and context identities']],
  [19,['supplied new run/context identities']],
  [21,['repository, CAD/CAM, simulation, build, deployment, manufacturing']],
  [22,['specialized deterministic tools']],
  [23,['dimensions, tolerances, interfaces','manufacturing intent']],
  [25,['datums/coordinates','dimensions/tolerances','manufacturing information']]
 ];
 for(const [stage,needles] of checks){const q=prompts.buildPromptRecord(stage,p).prompt;for(const needle of needles)if(!q.includes(needle))throw new Error(`Stage ${stage} lost specialist prompt semantics: ${needle}`);}
}
'''
    p.write_text(t)
